// Waypoints — home page renderer
// Reads ./manifest.json (regenerated by the GitHub Action on every push,
// see scripts/build-manifest.mjs) and renders the searchable index-card grid.

const grid = document.getElementById('grid');
const searchInput = document.getElementById('search');
const tagsEl = document.getElementById('tags');
const countEl = document.getElementById('count');

let entries = [];
let activeTag = null;

function pad(n) {
  return String(n).padStart(3, '0');
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso + 'T00:00:00');
  if (isNaN(d)) return iso;
  return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

function renderTags(all) {
  const unique = [...new Set(all.flatMap((e) => e.tags || []))].sort();
  tagsEl.innerHTML = '';
  unique.forEach((tag) => {
    const btn = document.createElement('button');
    btn.className = 'tag-chip';
    btn.type = 'button';
    btn.textContent = tag;
    btn.dataset.tag = tag;
    btn.addEventListener('click', () => {
      activeTag = activeTag === tag ? null : tag;
      renderGrid();
      [...tagsEl.children].forEach((c) => c.classList.toggle('active', c.dataset.tag === activeTag));
    });
    tagsEl.appendChild(btn);
  });
}

function renderGrid() {
  const q = searchInput.value.trim().toLowerCase();

  const filtered = entries.filter((e) => {
    const matchesTag = !activeTag || (e.tags || []).includes(activeTag);
    if (!matchesTag) return false;
    if (!q) return true;
    const haystack = [e.title, e.description, ...(e.tags || [])].join(' ').toLowerCase();
    return haystack.includes(q);
  });

  grid.innerHTML = '';

  if (filtered.length === 0) {
    grid.innerHTML = '<p class="status-msg">No matches. Try another word, or clear the filters.</p>';
    return;
  }

  filtered.forEach((entry, i) => {
    const a = document.createElement('a');
    a.className = 'card';
    a.href = entry.url;
    a.style.animationDelay = `${i * 30}ms`;
    a.innerHTML = `
      <span class="no">No. ${pad(i + 1)}</span>
      <h3>${entry.title}</h3>
      <p>${entry.description || ''}</p>
      <div class="meta">
        <span class="card-tags">${(entry.tags || []).map((t) => `<span>${t}</span>`).join('')}</span>
        <span>${formatDate(entry.date)}</span>
      </div>
    `;
    grid.appendChild(a);
  });
}

async function init() {
  try {
    const res = await fetch('./manifest.json', { cache: 'no-store' });
    if (!res.ok) throw new Error(`status ${res.status}`);
    entries = await res.json();
  } catch (err) {
    grid.innerHTML = `
      <p class="status-msg">
        Couldn't load manifest.json (${err.message}).<br>
        If you're previewing locally, serve the folder over HTTP (e.g. <code>python3 -m http.server</code>)
        rather than opening index.html directly — <code>fetch()</code> is blocked on the file:// protocol.<br>
        On the deployed site, check that the "Deploy site" GitHub Action has run successfully.
      </p>`;
    countEl.textContent = '';
    return;
  }

  entries.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  countEl.textContent = `${entries.length} ${entries.length === 1 ? 'entry' : 'entries'} logged`;
  renderTags(entries);
  renderGrid();
}

searchInput.addEventListener('input', renderGrid);
init();
